CREATE TABLE IF NOT EXISTS hr_employment_type (id CHAR(36) PRIMARY KEY, code VARCHAR(32) NOT NULL, name VARCHAR(120) NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, sort_order INT NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY hr_employment_type_code_unique (code), UNIQUE KEY hr_employment_type_name_unique (name)) DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO hr_employment_type (id, code, name, is_active, sort_order, created_at, updated_at) VALUES ('00000000-0000-4000-8000-000000000001', 'CIVIL_SERVANT', 'ข้าราชการ', 1, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()), ('00000000-0000-4000-8000-000000000002', 'GOVERNMENT_EMPLOYEE', 'พนักงานราชการ', 1, 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()), ('00000000-0000-4000-8000-000000000003', 'MOPH_EMPLOYEE', 'พนักงานกระทรวงสาธารณสุข (พกส.)', 1, 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()), ('00000000-0000-4000-8000-000000000004', 'PERMANENT_EMPLOYEE', 'ลูกจ้างประจำ', 1, 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()), ('00000000-0000-4000-8000-000000000005', 'TEMPORARY_EMPLOYEE', 'ลูกจ้างชั่วคราว', 1, 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()), ('00000000-0000-4000-8000-000000000006', 'DAILY_EMPLOYEE', 'ลูกจ้างรายวัน', 1, 6, UTC_TIMESTAMP(), UTC_TIMESTAMP());
CREATE TABLE IF NOT EXISTS hr_person_profile (person_id CHAR(36) PRIMARY KEY, name_prefix VARCHAR(32) NULL, first_name VARCHAR(120) NULL, last_name VARCHAR(120) NULL, gender VARCHAR(8) NULL, birth_date DATE NULL, phone VARCHAR(32) NULL, address VARCHAR(500) NULL, emergency_contact_name VARCHAR(255) NULL, emergency_contact_relationship VARCHAR(64) NULL, emergency_contact_phone VARCHAR(32) NULL, employment_type_id CHAR(36) NULL, appointed_on DATE NULL, position_level VARCHAR(120) NULL, updated_at DATETIME NOT NULL, KEY hr_person_profile_employment_type_index (employment_type_id), CONSTRAINT hr_person_profile_person_fk FOREIGN KEY (person_id) REFERENCES person(id), CONSTRAINT hr_person_profile_employment_type_fk FOREIGN KEY (employment_type_id) REFERENCES hr_employment_type(id)) DEFAULT CHARSET=utf8mb4;
